INSERT INTO `cursos` VALUES (4,15,6,'Idiomas','CUR-001','Curso integral de idiomas modernos enfocado en inglés conversacional y técnico.','images/cursos/idiomas.jpg','curso','2026-11-30','2027-03-22',16,0.00,1,'2026-06-23 08:29:47','2026-11-18 21:00:00'),(5,4,20,'Tecnología y Numéricas','CUR-002','Fundamentos matemáticos y lógicos aplicados a la resolución de problemas tecnológicos.','images/cursos/tecnologia_num.jpg','curso','2026-11-30','2027-03-22',16,0.00,1,'2026-06-23 08:30:35','2026-11-18 21:00:00'),(6,3,23,'Química','CUR-003','Curso de química general y orgánica, con prácticas experimentales y teoría molecular.','images/cursos/quimica_curso.jpg','curso','2026-11-30','2027-03-22',16,0.00,1,'2026-06-23 08:30:35','2026-11-18 21:00:00'),(7,5,22,'Física','CUR-004','Estudio de la mecánica clásica, termodinámica y electromagnetismo aplicado.','images/cursos/fisica_curso.jpg','curso','2026-11-30','2027-03-22',16,0.00,1,'2026-06-23 08:30:35','2026-11-18 21:00:00'),(8,13,7,'Cálculo','TAL-001','Taller intensivo de cálculo diferencial e integral para reforzar conocimientos básicos.','images/cursos/calculo.jpg','taller','2026-11-30','2027-01-11',6,0.00,1,'2026-06-23 08:30:35','2026-11-18 21:00:00'),(9,3,16,'Química','TAL-002','Taller práctico de formulación y balanceo de ecuaciones químicas.','images/cursos/quimica_taller.jpg','taller','2026-11-30','2027-01-11',6,0.00,1,'2026-06-23 08:30:35','2026-11-18 21:00:00'),(10,5,17,'Física','TAL-003','Taller de resolución de problemas de física vectorial y dinámica.','images/cursos/fisica_taller.jpg','taller','2026-11-30','2027-01-11',6,0.00,1,'2026-06-23 08:30:35','2026-11-18 21:00:00'),(11,11,20,'Programación','TAL-004','Taller práctico de algoritmos, estructuras de datos y lenguajes modernos.','images/cursos/programacion.jpg','taller','2026-11-30','2027-01-11',6,0.00,1,'2026-06-23 08:30:35','2026-11-18 21:00:00'),(12,14,21,'Tecnología Digital','TAL-005','Taller sobre arquitecturas de hardware, software libre y herramientas digitales.','images/cursos/tecnologia_digital.jpg','taller','2026-11-30','2027-01-11',6,0.00,1,'2026-06-23 08:30:35','2026-11-18 21:00:00'),(13,12,22,'Termodinámica','TAL-006','Taller avanzado sobre las leyes de la termodinámica y sistemas cerrados.','images/cursos/termodinamica.jpg','taller','2026-11-30','2027-01-11',6,0.00,1,'2026-06-23 08:30:35','2026-11-18 21:00:00'),(14,3,24,'Acto Solemne de Graduación Promoción UMC','EVE-001','Ceremonia oficial de conferimiento de títulos universitarios y medallas de grado en el Auditorio Principal.','images/cursos/graduacion.jpg','evento','2026-12-04','2026-12-04',1,15.00,1,'2026-11-11 06:50:34','2026-11-18 21:00:00'),(15,3,24,'Congreso Internacional Marítimo y Portuario','EVE-002','Ponencias magistrales sobre logística naviera, derecho marítimo y transporte acuático internacional.','images/cursos/congreso_maritimo.jpg','evento','2026-12-03','2026-12-03',1,10.00,1,'2026-11-11 06:50:34','2026-11-18 21:00:00'),(16,3,24,'Simposio de Innovación Tecnológica y Energías','EVE-003','Encuentro especial de proyectos de ingeniería, automatización, inteligencia artificial y energías limpias.','images/cursos/simposio_tech.jpg','evento','2026-12-02','2026-12-02',1,8.00,1,'2026-11-11 06:50:34','2026-11-18 21:00:00'),(17,17,8,'Legislación y Derecho Marítimo','CUR-005','Estudio integral del marco jurídico marítimo, convenios internacionales de navegación, contratos de fletamento y normativa portuaria.','images/cursos/idiomas.jpg','curso','2026-11-30','2027-03-22',16,0.00,1,'2026-11-18 21:00:00','2026-11-18 21:00:00'),(18,18,9,'Comercio Internacional y Aduanas','CUR-006','Análisis de operaciones de comercio exterior, regímenes aduaneros, valoración arancelaria y logística de transporte multimodal.','images/cursos/tecnologia_num.jpg','curso','2026-11-30','2027-03-22',16,0.00,1,'2026-11-18 21:00:00','2026-11-18 21:00:00'),(19,19,10,'Meteorología y Oceanografía','TAL-007','Taller práctico de interpretación meteorológica aplicada a la navegación, pronóstico de oleaje, mareas y fenómenos atmosféricos.','images/cursos/fisica_taller.jpg','taller','2026-11-30','2027-01-11',6,0.00,1,'2026-11-18 21:00:00','2026-11-18 21:00:00'),(20,20,11,'Navegación Costera y Astronómica','TAL-008','Taller de trazado de derrotas en cartas náuticas, posicionamiento por marcaciones, cálculo de rumbos y fundamentos astronómicos.','images/cursos/calculo.jpg','taller','2026-11-30','2027-01-11',6,0.00,1,'2026-11-18 21:00:00','2026-11-18 21:00:00'),(21,21,12,'Gestión Ambiental y Ecosistemas Costeros','CUR-007','Curso especializado en prevención de la contaminación marina, manejo sustentable de zonas costeras y auditorías ambientales.','images/cursos/quimica_curso.jpg','curso','2026-11-30','2027-03-22',16,0.00,1,'2026-11-18 21:00:00','2026-11-18 21:00:00'),(22,22,13,'Administración Portuaria y Logística','CUR-008','Planificación operativa de terminales marítimas, estiba y desestiba de carga, indicadores de rendimiento portuario y seguridad.','images/cursos/tecnologia_digital.jpg','curso','2026-11-30','2027-03-22',16,0.00,1,'2026-11-18 21:00:00','2026-11-18 21:00:00'),(23,23,14,'Seguridad Marítima y Salvamento','TAL-009','Taller práctico sobre protocolos internacionales de seguridad de la vida humana en el mar, supervivencia y gestión de emergencias.','images/cursos/termodinamica.jpg','taller','2026-11-30','2027-01-11',6,0.00,1,'2026-11-18 21:00:00','2026-11-18 21:00:00'),(24,24,15,'Turismo Sostenible y Gestión Hotelera','TAL-010','Taller enfocado en planificación de destinos turísticos costeros, industria de cruceros, calidad de servicio y sostenibilidad.','images/cursos/idiomas.jpg','taller','2026-11-30','2027-01-11',6,0.00,1,'2026-11-18 21:00:00','2026-11-18 21:00:00');
